```yaml
name: Copilot Setup Steps

on:
  pull_request:
    types: [opened, synchronize, reopened]
    branches:
      - main
      - master
  workflow_dispatch:

permissions:
  contents: read
  pull-requests: read

jobs:
  setup-copilot-context:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Get changed files
        id: changed-files
        uses: tj-actions/changed-files@v46
        with:
          files: |
            **/*.ps1
            **/*.psm1
            **/*.psd1
            **/*.md
            **/Tests/**
          files_ignore: |
            .github/**
            docs/**

      - name: Analyze PowerShell changes
        if: steps.changed-files.outputs.any_changed == 'true'
        shell: pwsh
        run: |
          $changedFiles = $env:CHANGED_POWERSHELL_FILES -split '\n'
          $newCommands = @()
          $modifiedCommands = @()

          foreach ($file in $changedFiles) {
            if ($file -match '\.ps1$' -or $file -match '\.psm1$') {
              $content = Get-Content $file -Raw

              # Detect new public commands
              if ($content -match 'function\s+(Get-SqlDsc\w+)') {
                $cmdName = $Matches[1]
                if ($cmdName -notin @('Get-SqlDscServerProtocol', 'Get-SqlDscServerProtocolName')) {
                  $newCommands += $cmdName
                }
              }

              # Detect parameter set changes
              if ($content -match 'ParameterSet\s*=\s*["''](\w+)["'']') {
                $modifiedCommands += $Matches[1]
              }
            }
          }

          Write-Output "## Copilot Context Summary"
          Write-Output ""
          Write-Output "### New Commands Detected"
          if ($newCommands.Count -gt 0) {
            foreach ($cmd in $newCommands) {
              Write-Output "- $cmd"
            }
          } else {
            Write-Output "- None"
          }

          Write-Output ""
          Write-Output "### Modified Parameter Sets"
          if ($modifiedCommands.Count -gt 0) {
            foreach ($set in $modifiedCommands) {
              Write-Output "- $set"
            }
          } else {
            Write-Output "- None"
          }

      - name: Validate PowerShell syntax
        if: steps.changed-files.outputs.any_changed == 'true'
        shell: pwsh
        run: |
          $psFiles = $env:CHANGED_POWERSHELL_FILES -split '\n'
          $errors = @()

          foreach ($file in $psFiles) {
            if (Test-Path $file) {
              try {
                $null = [System.Management.Automation.Language.Parser]::ParseFile($file, [ref]$null)
              }
              catch {
                $errors += "Syntax error in $file : $_"
              }
            }
          }

          if ($errors.Count -gt 0) {
            Write-Error "PowerShell syntax errors found:"
            $errors | ForEach-Object { Write-Error $_ }
            exit 1
          }
          else {
            Write-Output "All PowerShell files have valid syntax."
          }

      - name: Check for required patterns
        if: steps.changed-files.outputs.any_changed == 'true'
        shell: pwsh
        run: |
          $psFiles = $env:CHANGED_POWERSHELL_FILES -split '\n'
          $issues = @()

          foreach ($file in $psFiles) {
            if (Test-Path $file) {
              $content = Get-Content $file -Raw

              # Check for proper error handling
              if ($content -match 'New-InvalidOperationException') {
                $issues += "$file : Uses New-InvalidOperationException instead of `$PSCmdlet.ThrowTerminatingError()"
              }

              # Check for switch statement breaks
              if ($content -match 'switch\s*\(') {
                if ($content -notmatch 'break') {
                  $issues += "$file : Switch statement may be missing break statements"
                }
              }

              # Check file endings
              if ($content -notmatch '\n$') {
                $issues += "$file : File does not end with a newline"
              }
            }
          }

          if ($issues.Count -gt 0) {
            Write-Warning "Potential issues found:"
            $issues | ForEach-Object { Write-Warning $_ }
          }
          else {
            Write-Output "No obvious issues found in changed files."
          }

      - name: Generate Copilot instructions
        if: steps.changed-files.outputs.any_changed == 'true'
        shell: pwsh
        run: |
          $instructions = @"
          # Copilot Instructions for SqlServerDsc PR

          ## Context
          This PR involves changes to PowerShell DSC resources for SQL Server management.

          ## Key Changes
          - New command: Get-SqlDscManagedComputerInstance
          - Enhanced: Get-SqlDscServerProtocol with new parameter sets
          - Enhanced: Get-SqlDscServerProtocolName with improved switch logic

          ## Coding Standards
          - Use `$PSCmdlet.ThrowTerminatingError()` for errors
          - Include break statements in switch blocks
          - Ensure files end with exactly one blank line
          - Follow PSReviewUnusedParameter rules
          - Use proper variable casing

          ## Testing Requirements
          - All unit tests must pass
          - Test all parameter sets
          - Test pipeline input scenarios
          - Test error handling paths

          ## Documentation
          - Update comment-based help for all parameters
          - Update changelog with proper descriptions
          - Remove unused string resources
          "@

          $instructions | Out-File -FilePath "copilot-instructions.md"
          Write-Output "Generated Copilot instructions in copilot-instructions.md"

      - name: Upload Copilot instructions
        if: steps.changed-files.outputs.any_changed == 'true'
        uses: actions/upload-artifact@v4
        with:
          name: copilot-instructions
          path: copilot-instructions.md
          retention-days: 1
```

